"""Publish dated gate references and the rejected diagnostic fit, without game changes."""
from pathlib import Path
import json,hashlib,html,shutil
R=Path(__file__).resolve().parents[1]
W=Path('/Users/finbarr/.codex/worktrees/performance-audit/kyoto/.local/station-realism')
O=R/'notes/central-gate-registration';O.mkdir(exist_ok=True)
files={'lower-checks.json':'central-gate-registration-01/lower-checks.json','lower-report.json':'central-gate-lower-check-01/report.json','candidate-correspondences.json':'central-gate-registration-01/correspondences-03.json','candidate-fit.json':'central-gate-registration-01/fit-03/fit.json','candidate-source-proof.json':'central-gate-registration-01/source-proof-03.json','candidate-visibility.json':'central-gate-registration-01/visibility-03.json','previous-fit.json':'central-hall-maeda-01/fit-02/fit.json'}
receipts=[]
for name,src in files.items():
 data=(W/src).read_bytes();(O/name).write_bytes(data);receipts.append({'file':name,'source':str(W/src),'sha256':hashlib.sha256(data).hexdigest()})
(O/'manifest.json').write_text(json.dumps(receipts,indent=2)+'\n')
rows=json.loads((R/'sources.json').read_text());by={x['id']:x for x in rows}
sections=[]
for id in ['gate-central-2022','gate-central-2020','gate-universal-detail','hall-maeda-2026']:
 if id not in by:
  x=next(x for x in rows if x.get('local_file')=='photos/hall-maeda-2026.jpg')
 else:x=by[id]
 assert hashlib.sha256((R/x['local_file']).read_bytes()).hexdigest()==x['sha256']
 sections.append(f'<figure><a href="../../{html.escape(x["local_file"])}"><img src="../../{html.escape(x["local_file"])}" alt="{html.escape(x["title"])}"></a><figcaption>{html.escape(x["title"])} · {html.escape(x["publisher"])} · {html.escape(x.get("source_date","Unknown date"))}. <a href="{html.escape(x.get("parent_url",x["url"]))}">Original and attribution</a>. {html.escape(x["rights"])}</figcaption></figure>')
links=''.join(f'<li><a href="{n}">{n}</a></li>' for n in files)
(O/'index.html').write_text('''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Central gate evidence</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f2ec;color:#24382f;font:16px/1.55 system-ui}main{max-width:1100px;margin:auto;padding:24px}h1{line-height:1.15}figure{margin:24px 0}img{display:block;max-width:100%;max-height:760px;margin:auto}figcaption{font-size:14px;padding:12px;background:#e3e8df}a{color:#17654c;overflow-wrap:anywhere}.status{padding:18px;background:#f2dfb4}li{margin:8px 0}table{border-collapse:collapse;width:100%}td,th{text-align:left;padding:9px;border-bottom:1px solid #bac9bc}</style><main><a href="../../index.html">Research library</a><h1>Central gate: fixtures, architecture and registration limits</h1><p>28 September 2026. These are dated photographic references and diagnostic checks. Gate equipment has not moved in the game.</p><p class="status">The additional camera candidate is rejected. It passes image residuals but an opaque source object blocks 11 of 12 landmarks. The earlier camera also needs a reliable floor or depth check before placing the barriers.</p><h2>Construction details to carry forward</h2><ul><li>Separate the tall architectural portal from the recessed ticket barrier line and the paid platform beyond it.</li><li>Reconstruct the curved bridge soffit, upper glass balustrade, stone bands and circular side-wall recesses.</li><li>Model the departure-board rail and hanging rods together with the small cameras and ceiling lights.</li><li>Build stainless barrier bodies, dark top lids, blue reader trim, paddles and a wider accessible lane; confirm present-day lane count.</li><li>Align tactile paving, gate approach and the eastern office/machine frontage with the public well circulation.</li></ul><h2>Independent lower checks</h2><p>Four west-facade grille corners were inspected below the original upper landmarks. With the frozen earlier camera, errors are 19.68, 18.95, 24.40 and 23.78 pixels at 1200px width. The existing limit stays 24px; one check narrowly fails, within the stated 4px picking uncertainty. This alone does not prove a geometry defect.</p><p>A separate fit adds the two upper grille corners and withholds the two lower corners plus two original pier bases. Its fit RMS is 7.30px and largest withheld error 21.13px. Despite those residuals, source visibility fails: BuildingInstallation.1452 blocks 11 landmarks, about 1.8–2.2m from the camera. Do not use this candidate for construction dimensions.</p><h2>Reference photographs and access diagram</h2>'''+''.join(sections)+'''<h2>Evidence files</h2><p>The original camera and original observations are preserved. These receipts include exact source vertices and hashes.</p><ul>'''+links+'''<li><a href="manifest.json">Published evidence hashes</a></li><li><a href="../CENTRAL-GATE-REGISTRATION.md">Findings and next construction step</a></li></ul></main></html>''')
print(O)
